"""Create a serial-flash image from PlatformIO's actual bootloader/partition offsets."""
# AI: below section was generated by an AI
Import("env")
import json
from pathlib import Path


def create_factory(source, target, env):
    version = json.loads(Path("package.json").read_text())["version"]
    release = next(item[1] for item in env["CPPDEFINES"]
                   if isinstance(item, (tuple, list)) and item[0] == "WLED_RELEASE_NAME")
    release = release.replace('\\"', '').replace('"', '')
    images = [(int(str(offset), 0), Path(env.subst(str(filename))))
              for offset, filename in env["FLASH_EXTRA_IMAGES"]]
    images.append((int(str(env["ESP32_APP_OFFSET"]), 0), Path(str(target[0]))))
    images.sort(key=lambda pair: pair[0])
    merged = bytearray()
    for offset, image in images:
        data = image.read_bytes()
        if offset < len(merged):
            raise ValueError(f"Overlapping flash image: {image}")
        merged.extend(b'\xff' * (offset - len(merged)))
        merged.extend(data)
    destination = Path("build_output/release") / f"WLED_{version}_{release}_factory.bin"
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(merged)
    print(f"Factory image (flash at 0x0): {destination}")


env.AddPostAction("$BUILD_DIR/${PROGNAME}.bin", create_factory)
# AI: end
